/*
 * A087012  Numbers m such that the number of primes of form 4*k+1 between m
 *          and 2*m equals the number of primes of form 4*k+3 between m and
 *          2*m (inclusive).
 * https://oeis.org/A087012
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th integer m such that the number of primes p≡1
 *            (mod 4) in the interval [m, 2m] equals the number of primes p≡3
 *            (mod 4) in that interval. The sequence is generated by sieving
 *            all primes up to a fixed bound, building prefix‐sum tables for
 *            each residue class modulo 4, and collecting al...
 * Range:     u8 n <= 65, u16 n <= 2710, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>

seq_t a(idx_t n)
{
    /* static mutable state ------------------------------------------------- */
    static int initialized = 0;
    static seq_t *terms = NULL;
    static idx_t terms_len = 0, terms_cap = 0;

    static uint8_t *is_prime = NULL;
    static uint32_t *pi1 = NULL, *pi3 = NULL;
    static idx_t sieve_max = 0;

    /* parameters ----------------------------------------------------------- */
    const idx_t LIMIT   = 5000000ULL;   /* largest m to pre‑compute          */
    const idx_t SIEVE   = LIMIT * 2ULL;/* primes needed up to 2*m           */

    /* initialise sieve and prefix sums once --------------------------------- */
    if (!initialized)
    {
        /* allocate prime flags */
        is_prime = (uint8_t*)malloc((SIEVE + 1) * sizeof(uint8_t));
        if (!is_prime) return (seq_t)0;
        memset(is_prime, 1, (SIEVE + 1) * sizeof(uint8_t));
        is_prime[0] = is_prime[1] = 0;

        /* simple Eratosthenes sieve */
        for (idx_t i = 2; i * i <= SIEVE; ++i)
            if (is_prime[i])
                for (idx_t j = i * i; j <= SIEVE; j += i)
                    is_prime[j] = 0;

        /* allocate prefix sum arrays */
        pi1 = (uint32_t*)malloc((SIEVE + 1) * sizeof(uint32_t));
        pi3 = (uint32_t*)malloc((SIEVE + 1) * sizeof(uint32_t));
        if (!pi1 || !pi3) return (seq_t)0;

        pi1[0] = pi3[0] = 0;
        for (idx_t i = 1; i <= SIEVE; ++i)
        {
            pi1[i] = pi1[i-1];
            pi3[i] = pi3[i-1];
            if (is_prime[i])
            {
                if ((i & 3U) == 1U) ++pi1[i];
                else if ((i & 3U) == 3U) ++pi3[i];
            }
        }

        /* compute the sequence terms up to LIMIT */
        terms_cap = 200000;                  /* initial guess for capacity */
        terms = (seq_t*)malloc(terms_cap * sizeof(seq_t));
        terms_len = 0;
        if (!terms) return (seq_t)0;

        for (idx_t m = 1; m <= LIMIT; ++m)
        {
            idx_t r = 2 * m;
            uint32_t c1 = pi1[r] - pi1[m-1];
            uint32_t c3 = pi3[r] - pi3[m-1];
            if (c1 == c3)
            {
                if (terms_len == terms_cap)        /* grow array if needed */
                {
                    terms_cap *= 2;
                    seq_t *tmp = (seq_t*)realloc(terms, terms_cap * sizeof(seq_t));
                    if (!tmp) return (seq_t)0;
                    terms = tmp;
                }
                terms[terms_len++] = (seq_t)m;
            }
        }

        sieve_max = SIEVE;
        initialized = 1;
    }

    /* answer the query ------------------------------------------------------ */
    if (n == 0 || n > terms_len) return (seq_t)0;
    return terms[n-1];
}
